function CustomSelect({children,value,defaultValue,onChange,disabled=false,className="",required=false,searchable=false,searchPlaceholder="Search...", "aria-label":ariaLabel}){
 const [open,setOpen]=useState(false);
 const [internal,setInternal]=useState(defaultValue??"");
 const [menuPosition,setMenuPosition]=useState(null);
 const [query,setQuery]=useState("");
 const rootRef=React.useRef(null);
 const options=React.Children.toArray(children).filter(option=>React.isValidElement(option)&&option.type==="option").map(option=>({value:String(option.props.value??option.props.children??""),label:option.props.children,searchText:String(option.props["data-search"]??option.props.children??""),disabled:!!option.props.disabled}));
 const selected=value!==undefined?String(value):String(internal);
 const selectedOption=options.find(option=>option.value===selected);
 const visibleOptions=searchable?options.filter(option=>option.searchText.toLowerCase().includes(query.trim().toLowerCase())):options;
 useEffect(()=>{
  if(!open)return;
  function outside(event){if(!rootRef.current?.contains(event.target))setOpen(false)}
  function escape(event){if(event.key==="Escape")setOpen(false)}
  document.addEventListener("mousedown",outside);
  document.addEventListener("keydown",escape);
  return ()=>{document.removeEventListener("mousedown",outside);document.removeEventListener("keydown",escape)};
 },[open]);
 function toggleMenu(){
  if(disabled)return;
  if(!open){
   const rect=rootRef.current.getBoundingClientRect();
   const desiredHeight=Math.min(280,options.length*40+(searchable?58:10));
   const below=window.innerHeight-rect.bottom;
   const above=rect.top;
   const openAbove=below<desiredHeight&&above>below;
   const available=Math.max(90,Math.min(desiredHeight,(openAbove?above:below)-16));
   setMenuPosition({position:"fixed",left:rect.left,width:rect.width,top:openAbove?Math.max(8,rect.top-available-6):rect.bottom+6,maxHeight:available});
  }
  setQuery("");
  setOpen(current=>!current);
 }
 function choose(option){
  if(disabled||option.disabled)return;
  if(value===undefined)setInternal(defaultValue!==undefined?String(defaultValue):option.value);
  onChange?.({target:{value:option.value}});
  setOpen(false);
  setQuery("");
 }
 return <div className="custom-select" ref={rootRef}>
  <button type="button" className={"custom-select-trigger "+className} role="combobox" aria-haspopup="listbox" aria-expanded={open} aria-label={ariaLabel} aria-required={required||undefined} disabled={disabled} onClick={toggleMenu}>
   <span className="custom-select-value">{selectedOption?.label??options.find(option=>option.value==="")?.label??"Select"}</span><ChevronDown size={15} className="custom-select-chevron"/>
  </button>
  {open&&<div className="custom-select-menu" role="listbox" style={menuPosition||undefined}>
   {searchable&&<div className="custom-select-search"><Search size={14}/><input autoFocus value={query} onChange={event=>setQuery(event.target.value)} onKeyDown={event=>event.stopPropagation()} placeholder={searchPlaceholder} aria-label={searchPlaceholder}/></div>}
   {visibleOptions.length?visibleOptions.map((option,index)=><button type="button" key={option.value+"-"+index} className={"custom-select-option"+(option.value===selected?" selected":"")} role="option" aria-selected={option.value===selected} disabled={option.disabled} onClick={()=>choose(option)}>
    <span>{option.label}</span>{option.value===selected&&<Check size={15} className="custom-select-check"/>}
   </button>):<div className="custom-select-no-results">No matching guests found</div>}
  </div>}
  <select className="custom-select-native" tabIndex={-1} aria-hidden="true" required={required} disabled={disabled} value={selected} onChange={()=>{}}>{children}</select>
 </div>
}
function Badge({children}){return <span className={"badge "+String(children).toLowerCase().replaceAll(" ","-")}>{pretty(children)}</span>}
function Stat({label,value,icon:Icon,sub,onClick}){return <button className="stat" onClick={onClick}><div className="stat-top"><span>{label}</span><i><Icon size={18}/></i></div><strong>{value??"—"}</strong><small>{sub}</small></button>}
function LoginScreen({onLogin}){const [email,setEmail]=useState(""),[password,setPassword]=useState(""),[error,setError]=useState(""),[busy,setBusy]=useState(false);async function submit(e){e.preventDefault();setBusy(true);setError("");try{const r=await fetch(API+"/auth/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email,password})});const d=await r.json();if(!r.ok)throw new Error(d.error||"Sign in failed");localStorage.setItem("ezystay_token",d.token);onLogin(d.user)}catch(e){setError(e.message)}finally{setBusy(false)}}return <div className="login-page"><div className="login-card"><div className="logo login-logo"><span className="logo-mark"><Building2 size={21}/></span><span>EzyStay<small>HOTEL MANAGEMENT</small></span></div><h1>Welcome back</h1><p>Sign in to your hotel workspace.</p><form onSubmit={submit}><label className="field"><span>Email address</span><input type="email" required value={email} onChange={e=>setEmail(e.target.value)}/></label><label className="field"><span>Password</span><input type="password" required value={password} onChange={e=>setPassword(e.target.value)}/></label>{error&&<div className="login-error">{error}</div>}<button className="btn primary login-submit" disabled={busy}>{busy?"Signing in…":"Sign in"}</button></form><small className="login-foot">Access is provided by your hotel administrator.</small></div></div>}
function Empty({children="No records yet"}){return <div className="empty">{children}</div>}
function Panel({title,sub,action,children}){return <section className="panel"><div className="panel-head"><div><h3>{title}</h3>{sub&&<p>{sub}</p>}</div>{action}</div>{children}</section>}
function Modal({title,close,children}){return <div className="modal-shade" onMouseDown={e=>e.target===e.currentTarget&&close()}><div className="modal"><div className="modal-head"><h2>{title}</h2><button className="icon-btn" onClick={close}>×</button></div>{children}</div></div>}
function Field({label,children}){return <label className="field"><span>{label}</span>{children}</label>}

